--- # Manual MCP Server Deployment - Workaround for operator bug 565753858 # Deploy as static ArgoCD manifest (sync-wave 11, after org) # Set enableMcpServer: false in values-common-org.yaml to prevent operator interference apiVersion: apps/v1 kind: Deployment metadata: name: apigee-mcp-server-default-apigee-ocp-tech-e96d16b namespace: apigee-ap88257-hprd-dce13121 labels: app: apigee-mcp-server org: apigee-ocp-tech server-id: default annotations: argocd.argoproj.io/sync-wave: "11" spec: replicas: 1 selector: matchLabels: app: apigee-mcp-server org: apigee-ocp-tech server-id: default template: metadata: labels: app: apigee-mcp-server org: apigee-ocp-tech server-id: default spec: serviceAccountName: apigee-mcp-server-apigee-ocp-tech-e96d16b automountServiceAccountToken: true terminationGracePeriodSeconds: 30 imagePullSecrets: - name: image-pull-secret securityContext: runAsGroup: 998 runAsNonRoot: true runAsUser: 999 affinity: nodeAffinity: preferredDuringSchedulingIgnoredDuringExecution: - weight: 100 preference: matchExpressions: - key: workload operator: In values: - apigee-runtime requiredDuringSchedulingIgnoredDuringExecution: nodeSelectorTerms: - matchExpressions: - key: workload operator: In values: - apigee-runtime containers: # Container 1: apigee-mcp-server (envoy dataplane) - name: apigee-mcp-server image: private.fr2.icr.io/ap88257-hprd/apigee-release/hybrid/apigee-envoy-dataplane:1.17.0 args: - --service-node - $(POD_NAME) - --service-cluster - apigee-mcp-server-default env: - name: POD_NAME valueFrom: fieldRef: fieldPath: metadata.name - name: POD_NAMESPACE valueFrom: fieldRef: fieldPath: metadata.namespace - name: APIGEE_ORG value: apigee-ocp-tech - name: GOOGLE_APPLICATION_CREDENTIALS value: /etc/secret/client_secret.json - name: HTTP_FORWARD_PROXY value: "http://:@31" ports: - name: http containerPort: 80 protocol: TCP - name: https containerPort: 8443 protocol: TCP - name: status-port containerPort: 15021 protocol: TCP - name: admin containerPort: 15000 protocol: TCP readinessProbe: httpGet: path: /healthz/ready port: 15021 scheme: HTTP initialDelaySeconds: 2 periodSeconds: 2 failureThreshold: 5 resources: requests: cpu: 500m memory: 512Mi limits: cpu: "2" memory: 1Gi securityContext: allowPrivilegeEscalation: false capabilities: drop: - ALL privileged: false readOnlyRootFilesystem: true runAsNonRoot: true volumeMounts: - name: tls-volume mountPath: /opt/apigee/ssl - name: xds-config mountPath: /var/lib/envoy/xds - name: svc-account-volume mountPath: /etc/secret - name: fwi-token mountPath: /var/run/secrets/tokens - name: custom-ca mountPath: /etc/ssl/certs/ca-certificates.crt subPath: ca-certificates.crt # Container 2: apigee-mcp-server-config (watcher sidecar) - name: apigee-mcp-server-config image: private.fr2.icr.io/ap88257-hprd/apigee-release/hybrid/apigee-watcher:1.17.0 args: - --enable-mcp-sidecar - --mcp-server-id=default - --mcp-poll-interval=30s - --mcp-metrics-port=8843 - --liveness-readiness-port=8843 - --org=apigee-ocp-tech - --tls-path=/opt/apigee/ssl - --apigee-url=https://apigee.eu.rep.googleapis.com - --instance-id=ops-ap88257-test-cfdeb9ed - --http-forward-proxy=${HTTP_FORWARD_PROXY} env: - name: POD_NAME valueFrom: fieldRef: fieldPath: metadata.name - name: POD_NAMESPACE valueFrom: fieldRef: fieldPath: metadata.namespace - name: APIGEE_ORG value: apigee-ocp-tech - name: GOOGLE_APPLICATION_CREDENTIALS value: /etc/secret/client_secret.json - name: HTTP_FORWARD_PROXY value: "http://31" ports: - name: metrics containerPort: 8843 protocol: TCP livenessProbe: httpGet: path: /healthz port: 8843 scheme: HTTPS initialDelaySeconds: 30 periodSeconds: 5 failureThreshold: 12 resources: requests: cpu: 200m memory: 128Mi limits: cpu: 500m memory: 512Mi securityContext: allowPrivilegeEscalation: false capabilities: drop: - ALL privileged: false readOnlyRootFilesystem: true runAsNonRoot: true volumeMounts: - name: tls-volume mountPath: /opt/apigee/ssl - name: tmpfs mountPath: /tmp - name: svc-account-volume mountPath: /etc/secret - name: custom-ca mountPath: /etc/ssl/certs/ca-certificates.crt subPath: ca-certificates.crt volumes: # Volumes existants (générés par l'operator) - name: tls-volume secret: secretName: apigee-mcp-server-apigee-ocp-tech-e96d16b-d79c8de-tls - name: tmpfs emptyDir: {} - name: xds-config emptyDir: {} - name: svc-account-volume secret: secretName: apigee-mcp-server-apigee-ocp-tech-e96d16b-svc-account # Volumes MANQUANTS - corrige le bug 565753858 - name: fwi-token emptyDir: {} - name: custom-ca configMap: name: bnpp-ca-bundle-full defaultMode: 420 --- apiVersion: v1 kind: Service metadata: name: apigee-mcp-server-default-apigee-ocp-tech-e96d16b namespace: apigee-ap88257-hprd-dce13121 labels: app: apigee-mcp-server org: apigee-ocp-tech server-id: default annotations: argocd.argoproj.io/sync-wave: "11" spec: type: ClusterIP selector: app: apigee-mcp-server org: apigee-ocp-tech server-id: default ports: - name: http port: 80 targetPort: 80 protocol: TCP - name: https port: 443 targetPort: 8443 protocol: TCP - name: status-port port: 15021 targetPort: 15021 protocol: TCP - name: admin port: 15000 targetPort: 15000 protocol: TCP
